-- XPETIS · seed 0002 · Tassonomia geografica
--
-- GENERATO da supabase/scripts/genera_geo.mjs a partire da
-- xpetis_destinazioni_v2.json. Non modificare a mano: rigenerare.
-- Attese: 6 continenti, 14 macro-aree, 129 stati, 244 regioni, 188 città.

-- Regole di selezione dichiarate dalla tassonomia
-- (le regioni italiane NON filtrano: deviazione 7 del PIANO, confermata il 27/09/2026):
--   selezionabili: macro_area, state, italian_region
--   solo cercabili: continent, city, foreign_region
--   Cercando 'Italia' il sistema suggerisce le 20 regioni italiane (tutte selezionabili).

-- Tutto in una transazione: rigirato sopra dati esistenti, un giro fermato
-- da una guardia non deve lasciare mezza potatura.
begin;

-- Guardia: nel database non ci devono essere continenti, macro-aree, stati o
-- regioni che il file non ha. Non si cancellano da qui (uno stato ha dietro
-- td_countries e quiz_responses): si ferma tutto e lo si dice.
do $$
declare v_extra text;
begin
  select string_agg(x, ', ') into v_extra from (
    select 'continente ' || code as x from geo_continents where code <> all (array['europa', 'africa', 'asia', 'americhe', 'oceania', 'antartide']::text[])
    union all select 'macro-area ' || code from geo_macro_areas where code <> all (array['europa_est_e_caucaso', 'europa_nord', 'europa_sud', 'africa_sub_sahariana', 'isole_delloceano_indiano', 'nord_africa', 'asia_centrale_e_subcontinente_indiano', 'asia_orientale_e_sud_est_asiatico', 'medio_oriente', 'centro_america_e_caraibi', 'nord_america', 'sud_america', 'oceania', 'antartide']::text[])
