     where (country_code || '/' || slug) <> all (array['armenia/armenia', 'azerbaijan/azerbaijan', 'bielorussia/bielorussia', 'georgia/georgia', 'moldavia/moldavia', 'russia/russia_europea', 'russia/siberia_e_estremo_oriente', 'ucraina/ucraina', 'austria/vienna', 'austria/tirolo', 'austria/salisburghese', 'belgio/fiandre', 'belgio/vallonia', 'belgio/bruxelles', 'danimarca/selandia', 'danimarca/jutland', 'estonia/estonia', 'finlandia/finlandia_meridionale', 'finlandia/lapponia_finlandese', 'francia/île_de_france', 'francia/provenza_costa_azzurra', 'francia/normandia', 'francia/bretagna', 'francia/alvernia_rodano_alpi', 'francia/nuova_aquitania', 'germania/baviera', 'germania/berlino', 'germania/renania_settentrionale_vestfalia', 'germania/amburgo', 'germania/sassonia', 'irlanda/leinster', 'irlanda/munster', 'irlanda/connacht', 'islanda/reykjavik_e_sud', 'islanda/nord_e_ovest', 'lettonia/lettonia', 'lituania/lituania', 'lussemburgo/lussemburgo', 'norvegia/norvegia_meridionale', 'norvegia/fiordi_occidentali', 'norvegia/norvegia_settentrionale', 'paesi_bassi/olanda_settentrionale', 'paesi_bassi/olanda_meridionale', 'paesi_bassi/utrecht', 'polonia/masovia', 'polonia/piccola_polonia', 'polonia/pomerania', 'regno_unito/inghilterra', 'regno_unito/scozia', 'regno_unito/galles', 'regno_unito/irlanda_del_nord', 'repubblica_ceca/boemia', 'repubblica_ceca/moravia', 'slovacchia/bratislava', 'slovacchia/alti_tatra', 'svezia/stoccolma', 'svezia/lapponia_svedese', 'svezia/götaland', 'svizzera/romandia', 'svizzera/svizzera_tedesca', 'svizzera/ticino', 'svizzera/grigioni', 'ungheria/budapest', 'ungheria/transdanubio', 'albania/albania', 'bosnia_ed_erzegovina/bosnia_ed_erzegovina', 'bulgaria/bulgaria', 'cipro/cipro', 'croazia/dalmazia', 'croazia/istria', 'croazia/zagabria_e_continentale', 'grecia/attica', 'grecia/isole_cicladi', 'grecia/creta', 'grecia/isole_ionie', 'grecia/peloponneso', 'italia/abruzzo', 'italia/basilicata', 'italia/calabria', 'italia/campania', 'italia/emilia_romagna