', 'giappone/kyushu_e_okinawa', 'indonesia/bali_e_nusa_tenggara', 'indonesia/giava', 'indonesia/sumatra_e_borneo', 'indonesia/sulawesi_e_papua', 'laos/laos', 'malesia/malesia_peninsulare', 'malesia/borneo_malese', 'mongolia/mongolia', 'myanmar/myanmar', 'singapore/singapore', 'taiwan/taiwan', 'thailandia/thailandia_del_nord', 'thailandia/thailandia_centrale', 'thailandia/thailandia_del_sud', 'vietnam/vietnam_del_nord', 'vietnam/vietnam_centrale', 'vietnam/vietnam_del_sud', 'arabia_saudita/arabia_saudita', 'emirati_arabi_uniti/emirati_arabi_uniti', 'giordania/giordania', 'iran/iran', 'israele/israele', 'libano/libano', 'oman/oman', 'qatar/qatar', 'belize/belize', 'costa_rica/costa_rica', 'cuba/cuba', 'giamaica/giamaica', 'guatemala/guatemala', 'honduras/honduras', 'messico/yucatán_e_caraibi', 'messico/messico_centrale', 'messico/bassa_california', 'nicaragua/nicaragua', 'panama/panama', 'repubblica_dominicana/repubblica_dominicana', 'canada/canada_orientale', 'canada/canada_occidentale', 'stati_uniti/costa_est', 'stati_uniti/costa_ovest', 'stati_uniti/sud', 'stati_uniti/midwest_e_montagne', 'stati_uniti/hawaii_e_alaska', 'argentina/argentina_del_nord', 'argentina/patagonia_argentina', 'bolivia/bolivia', 'brasile/sud_est', 'brasile/nord_est', 'brasile/amazzonia_e_pantanal', 'cile/cile_del_nord_e_centro', 'cile/patagonia_cilena', 'cile/isola_di_pasqua', 'colombia/colombia', 'ecuador/ecuador_continentale', 'ecuador/galápagos', 'paraguay/paraguay', 'peru/peru', 'uruguay/uruguay', 'venezuela/venezuela', 'australia/australia_orientale', 'australia/australia_centrale_e_ovest', 'australia/tasmania', 'fiji/fiji', 'isole_cook/isole_cook', 'nuova_zelanda/isola_del_nord', 'nuova_zelanda/isola_del_sud', 'polinesia_francese/polinesia_francese', 'samoa/samoa', 'tonga/tonga', 'antartide/antartide']::text[])
  ) e;
  if v_extra is not null then
    raise exception 'Il database ha righe geografiche che xpetis_destinazioni_v2.json non ha più: %. Toglierle è una decisione, non una rigenerazione.', v_extra;
  end if;
end $$;

on conflict (code) do update set
  name_it = excluded.name_it, is_selectable = excluded.is_selectable, sort_order = excluded.sort_order;

on conflict (code) do update set
  continent_code = excluded.continent_code, name_it = excluded.name_it,
  is_selectable = excluded.is_selectable, sort_order = excluded.sort_order;

on conflict (code) do update set
  macro_area_code = excluded.macro_area_code, name_it = excluded.name_it,
  is_selectable = excluded.is_selectable, sort_order = excluded.sort_order;

on conflict (country_code, slug) do update set
  name_it = excluded.name_it, kind = excluded.kind, is_selectable = excluded.is_selectable;

-- Le città si agganciano alla regione risolvendo (stato, slug regione). Stanno
-- in una tabella temporanea perché servono tre volte: per la guardia, per
-- l'inserimento e per la potatura.
-- Il drop in testa rende il seed rilanciabile anche dopo un giro fermato a metà.
drop table if exists geo_citta_attese;
create temp table geo_citta_attese (
  country_code text, region_slug text, city_slug text, city_name text, is_selectable boolean
);

-- Guardia: una città senza la sua regione verrebbe scartata dalla join in
-- silenzio. Meglio fermarsi.
do $$
declare v_orfane text;
begin
  select string_agg(v.country_code || '/' || v.region_slug || '/' || v.city_slug, ', ') into v_orfane
    from geo_citta_attese v
   where not exists (select 1 from geo_regions r
                      where r.country_code = v.country_code and r.slug = v.region_slug);
  if v_orfane is not null then
    raise exception 'Città senza regione nel database: %', v_orfane;
  end if;
end $$;

select v.country_code, r.id, v.city_slug, v.city_name, v.is_selectable
  from geo_citta_attese v
  join geo_regions r on r.country_code = v.country_code and r.slug = v.region_slug
on conflict (region_id, slug) do update set
  name_it = excluded.name_it, is_selectable = excluded.is_selectable;

-- La potatura: le città che il file non ha più se ne vanno. Nessuna chiave
-- esterna punta a geo_cities (verificato il 27 settembre 2026), quindi non
-- trascina niente con sé. Su un database vuoto non fa nulla.
delete from geo_cities c
 where not exists (
   select 1 from geo_citta_attese v
     join geo_regions r on r.country_code = v.country_code and r.slug = v.region_slug
    where r.id = c.region_id and v.city_slug = c.slug);

drop table geo_citta_attese;

commit;
